root.script:
  		function CreateItem()
		{
			var weaponIdx = $.GetContextPanel().FindChildInLayoutFile('Weaponidx').GetSelected().GetAttributeString( "value", "" );
            var skinIdx = GetSelectedSkinId();
            var seedIdx = $.GetContextPanel().FindChildInLayoutFile('seedIdx').text;

			if(skinIdx == '')
				skinIdx = 2;

			if(seedIdx == '')
				seedIdx = Math.floor(Math.random() * 1000) + 1;

            GameInterfaceAPI.ConsoleCommand(`csgo_econ_action_preview S00000${weaponIdx}A00000${skinIdx}D00000${seedIdx}`);
		}

		function UpdateWeaponPreview()
		{
			var weaponIdx = $.GetContextPanel().FindChildInLayoutFile('Weaponidx').GetSelected().GetAttributeString( "value", "" );
            var skinIdx = GetSelectedSkinId();

			var itemId = InventoryAPI.GetFauxItemIDFromDefAndPaintIndex( weaponIdx, skinIdx );

			var elPanel = $.GetContextPanel().FindChildInLayoutFile('ItemPreview');
			elPanel.SetScene( "resource/ui/econ/ItemModelPanelCharWeaponInspect.res",
				'img://inventory_'+itemId,
				false
			);
		}

		function Inspect()
		{
			var itemIdx = $.GetContextPanel().FindChildInLayoutFile('Weaponidx').GetSelected().GetAttributeString( "value", "" );
            var skinIdx = GetSelectedSkinId();

			if(skinIdx == '')
				skinIdx = 2;

			var itemId = InventoryAPI.GetFauxItemIDFromDefAndPaintIndex( itemIdx, skinIdx );

			UiToolkitAPI.ShowCustomLayoutPopupParameters(
				'',
				'file://{resources}/layout/popups/popup_inventory_inspect.xml',
				'itemid=' + itemId +
				'&' + 'inspectonly=true' +
				'&' + 'viewfunc=primary',
				'none'
			);
		}

		function GetSelectedSkinId()
		{
			var skinId = $.GetContextPanel().FindChildInLayoutFile('skinIdx').GetSelected().GetAttributeString( "value", "" );

			if(skinId == 'showfromfield')
				skinId = $.GetContextPanel().FindChildInLayoutFile('skinIdxField').text;

			//$.GetContextPanel().FindChildInLayoutFile('skinIdxField').SetHasClass('hidden', skinId != 'showfromfield');

			return skinId;
		}

		function FillItems()
		{
			for (let i = 0; i < 2000; i++) {
				var itemId = InventoryAPI.GetFauxItemIDFromDefAndPaintIndex( 1, i );
				var itemName = InventoryAPI.GetItemName(itemId);
				if(itemName)
					itemName = itemName.split(' | ')[1];

				if(itemName == '' || itemName == undefined || !itemName)
					continue;

				var elDropdown = $.GetContextPanel().FindChildInLayoutFile('skinIdx');
				var newEntry = $.CreatePanel('Label', elDropdown, "item"+i, {
						class: 'DropDownMenu Width-250 White',
						value: i,
						text: itemName
					});

				elDropdown.AddOption(newEntry);
			}
			$.GetContextPanel().FindChildInLayoutFile('Weaponidx').SetSelected('weapon_glock');
			elDropdown.SetSelected( 'item2' );
		}
		$.CreatePanel('ItemPreviewPanel', $.GetContextPanel().FindChildInLayoutFile('Content'), 'ItemPreview', {
			manifest: 'resource/ui/econ/ItemModelPanelCharWeaponInspect.res',
			enable_floorshadow: true,
			mouse_rotate: true
		});
		FillItems();
		UpdateWeaponPreview();
